// Meta batches events. Flatten to one item per comment, and drop
// anything that is not a comment (edits, likes, echoes of our own replies).
const out = [];
for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  for (const entry of body.entry ?? []) {
    // entry.id is our own Instagram professional account. It is read from the
    // payload, not an environment variable: $env is blocked by default on
    // n8n Cloud and n8n 2.x, and an unset variable would silently switch the
    // echo check below off.
    const ownId = String(entry.id ?? '');
    if (!ownId) continue;
    for (const change of entry.changes ?? []) {
      if (change.field !== 'comments') continue;
      const v = change.value ?? {};
      const fromId = String(v.from?.id ?? '');
      const commentId = String(v.id ?? '');
      if (!fromId || !commentId) continue;
      // Our own replies come back through the same webhook. Without this the
      // workflow answers itself, forever.
      if (fromId === ownId) continue;
      out.push({
        json: {
          igAccountId: ownId,
          commentId,
          mediaId: v.media?.id,
          text: String(v.text ?? '').trim(),
          fromId,
          username: v.from?.username,
          receivedAt: new Date().toISOString()
        }
      });
    }
  }
}
return out;

// Keyword table. Whole-word match, case-insensitive, so "guiding" does not
// trigger the "GUIDE" rule. Longest keyword wins when two match.
const RULES = [
  { keyword: 'GUIDE',  link: 'https://example.com/skin-guide',   reply: 'Sent it over. Check your DMs.' },
  { keyword: 'PRICES', link: 'https://example.com/pricing',      reply: 'Prices are in your DMs.' },
  { keyword: 'RESTOCK',link: 'https://example.com/restock-alert',reply: 'Popped the restock link in your DMs.' }
];
const out = [];
for (const item of $input.all()) {
  const text = item.json.text ?? '';
  const hits = RULES.filter(r => new RegExp(`\\b${r.keyword}\\b`, 'i').test(text))
                    .sort((a, b) => b.keyword.length - a.keyword.length);
  if (!hits.length) continue;
  out.push({ json: { ...item.json, matched: hits[0].keyword, link: hits[0].link, publicReply: hits[0].reply } });
}
return out;

// One DM per person per day. The sent log is read once, then every comment
// in this batch is checked against it. (A per-comment lookup node would
// replace each comment with a sheet row, losing the comment id and the link
// the next nodes need.)
const today = $now.toFormat('yyyy-MM-dd');
const sentToday = new Set(
  $('Read sent log').all()
    .map(i => i.json)
    .filter(r => String(r.sentAt ?? '').slice(0, 10) === today)
    .map(r => String(r.fromId ?? ''))
    .filter(Boolean)
);
const out = [];
for (const item of $('Match keyword').all()) {
  const fromId = String(item.json.fromId ?? '');
  if (!fromId || sentToday.has(fromId)) continue;
  sentToday.add(fromId);   // two comments from one person in one batch: one DM
  out.push({ json: item.json });
}
return out;

// Keep only the comments whose DM actually went out. The Graph API node
// returns exactly one item per input, in order, so results pair with the
// comments by index. A failed DM (comment older than seven days, or already
// privately replied to) stops here: no public "check your DMs" under it, and
// no log row, so it does not count against that person's one DM today.
const comments = $('Not messaged today').all();
const out = [];
$input.all().forEach((item, i) => {
  if (!item.json.message_id || !comments[i]) return;
  out.push({ json: comments[i].json });
});
return out;
